type UserProfileResponse struct {
	Id            int64  `json:"id"`
	Nickname      string `json:"nickname"`
	Avatar        string `json:"avatar"`          // 完整访问 URL(永久有效),前端直接渲染
	AvatarFileKey string `json:"avatar_file_key"` // 原始 file_key(纯路径),前端缓存 + dirty 比较用
	Phone         string `json:"phone"`
	Status        int    `json:"status"`
	CreatedAt     string `json:"created_at"`
}

type V4SignatureHeaders struct {
	XOssSignatureVersion string `json:"x_oss_signature_version"`
	XOssCredential       string `json:"x_oss_credential"`
	XOssDate             string `json:"x_oss_date"`
	XOssSignature        string `json:"x_oss_signature"`
}
